const API_URL="https://bkcrgfkhgjypvzwubwrh.supabase.co/functions/v1/news-feedback",REASONS=["D","NR","NW"],norm=v=>String(v||"").toLowerCase().replace(/\s+/g," ").trim();export async function loadPools(){const pools=new Map(REASONS.map(reason=>[reason,[]]));try{const response=await fetch(API_URL,{method:"GET",cache:"no-store",headers:{Accept:"application/json"}});if(!response.ok)throw new Error(`feedback read ${response.status}`);const data=await response.json();for(const reason of REASONS)pools.set(reason,Array.isArray(data?.pools?.[reason])?data.pools[reason]:[])}catch(error){console.warn("V6 feedback pools unavailable:",error)}return pools}export async function submitFeedback(reason,story,category){if(!REASONS.includes(reason))throw new Error("invalid feedback reason");const capturedAt=new Date().toISOString(),response=await fetch(API_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({reason,category,title:story.title,url:story.url,source:story.source,description:story.summary||"",why:story.why_matters||"",capturedAt})});if(!response.ok)throw new Error(`feedback write ${response.status}`);return{reason,category,title:story.title,url:story.url,source:story.source,title_key:norm(story.title),url_key:norm(story.url),source_key:norm(story.source),captured_at:capturedAt}}
